# Chapter 25 Motion of charged particles — part a: 25.1 to 25.3.
QE, ME, MP, MA = 1.60e-19, 9.11e-31, 1.67e-27, 6.64e-27

# ═════════════════════════ 25.1 Force on a moving charge (17/16/9) ═════════════════════════
lesson('25.1')
N('E', 2, 'An α-particle (charge +2e) moves at 3.0 × 10⁶ m s⁻¹ at right angles to a field of 0.50 T. Calculate the magnetic force on it, in units of 10⁻¹³ N.' + take('e'), 2 * QE * 3.0e6 * 0.50, '10⁻¹³ N',
  f'F = BQv = 0.50 × 2 × 1.60 × 10⁻¹⁹ × 3.0 × 10⁶ = {sf(0.5 * 2 * QE * 3e6)} N', ['C1: F = BQv with Q = 2e'], sig=2, aq='F')
M('E', 1, 'When Fleming\'s left-hand rule is used for a moving positive charge, which way does the second finger point?', 'Along the velocity of the charge', ['Along the magnetic field', 'Along the force', 'Opposite to the velocity'], 'A moving positive charge is a conventional current in its direction of motion.')
M('E', 1, 'For an electron beam, in which direction should the "current" finger of the left-hand rule point?', 'Opposite to the electron\'s velocity', ['Along the electron\'s velocity', 'Along the magnetic field', 'Along the force'], 'Conventional current is opposite to the flow of negative charge.')
N('E', 2, 'A proton moves at 4.0 × 10⁵ m s⁻¹ at 60° to a magnetic field of 0.25 T. Calculate the magnetic force on it, in units of 10⁻¹⁴ N.' + take('e'), QE * 4.0e5 * 0.25 * sin(radians(60)), '10⁻¹⁴ N',
  f'F = BQv sin θ = 0.25 × 1.60 × 10⁻¹⁹ × 4.0 × 10⁵ × sin 60° = {sf(0.25 * QE * 4e5 * sin(radians(60)))} N', ['C1: F = BQv sin θ'], aq='F')
M('E', 1, 'In F = BQv sin θ, what does θ represent?', 'The angle between the velocity of the charge and the magnetic field', ['The angle between the force and the field', 'The angle between the force and the velocity', 'The angle of the field to the horizontal'], 'Only the velocity component at right angles to B contributes.')
N('E', 2, 'An electron moving at right angles to a 0.50 T field experiences a magnetic force of 6.4 × 10⁻¹⁴ N. Calculate its speed.' + take('e'), 6.4e-14 / (QE * 0.50), 'm s⁻¹',
  'v = F/(BQ) = 6.4 × 10⁻¹⁴ ÷ (0.50 × 1.60 × 10⁻¹⁹) = 8.0 × 10⁵ m s⁻¹', ['C1: v = F/(BQ)'], sig=2, aq='v')
M('E', 1, 'What magnetic force acts on a charged particle that is at rest in a magnetic field?', 'None', ['BQ', 'BQ multiplied by the speed of light', 'A force along the field lines'], 'F = BQv, and with v = 0 the magnetic force is zero.')
N('E', 2, 'A proton moving at 1.0 × 10⁶ m s⁻¹ at right angles to a magnetic field experiences a force of 3.2 × 10⁻¹⁴ N. Calculate the flux density.' + take('e'), 3.2e-14 / (QE * 1.0e6), 'T',
  'B = F/(Qv) = 3.2 × 10⁻¹⁴ ÷ (1.60 × 10⁻¹⁹ × 1.0 × 10⁶) = 0.20 T', ['C1: B = F/(Qv)'], sig=2, aq='B')
M('E', 1, 'The speed of a charged particle moving at right angles to a magnetic field doubles. What happens to the magnetic force on it?', 'It doubles', ['It halves', 'It quadruples', 'It stays the same'], 'F = BQv, so with B and Q fixed the force is proportional to the speed.')
N('E', 2, 'What magnetic force, in units of 10⁻¹⁴ N, acts on a doubly charged ion crossing a 1.0 T field at right angles with speed 2.0 × 10⁵ m s⁻¹?' + take('e'), 2 * QE * 2.0e5 * 1.0, '10⁻¹⁴ N',
  f'F = BQv = 1.0 × 2 × 1.60 × 10⁻¹⁹ × 2.0 × 10⁵ = {sf(2 * QE * 2e5)} N', ['C1: Q = 2e'], sig=2, aq='F')
M('E', 1, 'A charged particle moves through a uniform magnetic field and no other force acts. What happens to its kinetic energy?', 'It stays the same', ['It increases steadily', 'It decreases steadily', 'It becomes zero'], 'The force is always perpendicular to the motion, so no work is done.')
N('E', 1, 'A charged particle feels a magnetic force of 2.0 × 10⁻¹⁴ N when moving at right angles to a field. What force does it feel, in units of 10⁻¹⁴ N, moving at the same speed at 30° to the field?', 2.0e-14 * sin(radians(30)), '10⁻¹⁴ N',
  'F = 2.0 × 10⁻¹⁴ × sin 30° = 1.0 × 10⁻¹⁴ N', [], sig=2, aq='F')
M('E', 1, 'A proton moves due east through a magnetic field that points vertically upwards. In which direction is the force on it?', 'Due south', ['Due north', 'Vertically downwards', 'Due west'], 'Left-hand rule: first finger up, second finger east (positive charge), thumb points south.')
N('E', 2, 'A proton and an α-particle move at the same speed at right angles to the same magnetic field. Calculate (force on α-particle) ÷ (force on proton).', 2.0, None,
  'F = BQv and the α-particle has charge 2e: ratio = 2 × 1.60 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 2.0', ['C1: F ∝ Q'], sig=2, aq='ratio')
M('E', 1, 'Which step links F = BIL to the force on a single moving charge, F = BQv?', 'A charge Q moving at speed v forms a current I = Q/t over a length L = vt, so BIL = BQv', ['The current is equal to the speed of the charge', 'The length is equal to the charge', 'B is equal to Q/v'], 'IL = (Q/t)(vt) = Qv.')
N('E', 2, 'An electron moves at 1.0 × 10⁷ m s⁻¹ at right angles to the Earth\'s field of 5.0 × 10⁻⁵ T. Calculate the magnetic force on it, in units of 10⁻¹⁷ N.' + take('e'), QE * 1.0e7 * 5.0e-5, '10⁻¹⁷ N',
  f'F = BQv = 5.0 × 10⁻⁵ × 1.60 × 10⁻¹⁹ × 1.0 × 10⁷ = {sf(5e-5 * QE * 1e7)} N', ['C1: F = BQv'], sig=2, aq='F')
M('E', 1, 'A beam of neutrons passes through a strong magnetic field. What happens to the beam?', 'It is not deflected, because neutrons are uncharged', ['It curves into a circle', 'It is deflected towards the north pole', 'It slows down'], 'The magnetic force needs a charge: F = BQv with Q = 0.')
# medium
N('M', 3, 'In an old television tube, electrons moving at 3.0 × 10⁷ m s⁻¹ cross a deflecting field of 2.0 mT at right angles. Calculate the acceleration of an electron.' + take('e', 'me'), QE * 3.0e7 * 2.0e-3 / ME, 'm s⁻²',
  f'F = BQv = 2.0 × 10⁻³ × 1.60 × 10⁻¹⁹ × 3.0 × 10⁷ = {sf(2e-3 * QE * 3e7)} N. a = F/m = {sf(2e-3 * QE * 3e7, 4)} ÷ 9.11 × 10⁻³¹ = {sf(2e-3 * QE * 3e7 / ME)} m s⁻²', ['C1: F = BQv', 'C1: a = F/m'], aq='a')
N('M', 3, 'Free electrons drift at 2.0 × 10⁻⁴ m s⁻¹ along a copper wire that lies at right angles to a 0.50 T field. Calculate the magnetic force on one electron, in units of 10⁻²³ N.' + take('e'), QE * 2.0e-4 * 0.50, '10⁻²³ N',
  f'F = BQv = 0.50 × 1.60 × 10⁻¹⁹ × 2.0 × 10⁻⁴ = {sf(0.5 * QE * 2e-4)} N: tiny, but there are about 10²² free electrons in each centimetre of wire', ['C1: F = Bev', 'C1: substitution'], sig=2, aq='F')
M('M', 3, 'A proton and an electron move in the same direction at the same speed through the same magnetic field. How do the magnetic forces on them compare?', 'Equal in size and opposite in direction', ['Equal in size and in the same direction', 'The force on the proton is 1840 times larger', 'The force on the electron is 1840 times larger'], 'F = BQv: same |Q|, v and B; the sign of Q reverses the direction.', ['C1: same |Q|', 'C1: opposite sign gives opposite force'])
N('M', 4, 'A charged dust grain of mass 1.0 × 10⁻¹² kg carries 1.6 × 10⁻¹⁵ C and moves at 50 m s⁻¹ at right angles to a field of 0.40 T. Calculate its acceleration due to the magnetic force.', 0.40 * 1.6e-15 * 50 / 1.0e-12, 'm s⁻²',
  'F = BQv = 0.40 × 1.6 × 10⁻¹⁵ × 50 = 3.2 × 10⁻¹⁴ N. a = F/m = 3.2 × 10⁻¹⁴ ÷ 1.0 × 10⁻¹² = 0.032 m s⁻²', ['C1: F = BQv', 'C1: a = F/m', 'B1: magnetic effect tiny for a slow, heavy grain'], sig=2, aq='a')
N('M', 3, 'With speed 5.0 × 10⁶ m s⁻¹, an electron crosses a 0.10 T field at 40° to the field lines. Find the magnetic force on it, in units of 10⁻¹⁴ N.' + take('e'), QE * 5.0e6 * 0.10 * sin(radians(40)), '10⁻¹⁴ N',
  f'F = BQv sin θ = 0.10 × 1.60 × 10⁻¹⁹ × 5.0 × 10⁶ × sin 40° = {sf(0.1 * QE * 5e6 * sin(radians(40)))} N', ['C1: F = BQv sin θ', 'C1: substitution'], aq='F')
M('M', 3, 'A charged particle enters a uniform magnetic field with its velocity at an acute angle to the field lines. What is the shape of its path?', 'A helix (spiral) along the field lines', ['A circle in a plane containing the field', 'A straight line along the field', 'A parabola'], 'The perpendicular velocity component gives circular motion; the parallel component carries it along the field.', ['C1: components of velocity', 'C1: circle plus drift gives helix'])
N('M', 3, 'At what speed must a proton move at right angles to a 0.10 T field to feel a magnetic force of 1.0 × 10⁻¹³ N?' + take('e'), 1.0e-13 / (QE * 0.10), 'm s⁻¹',
  f'v = F/(BQ) = 1.0 × 10⁻¹³ ÷ (0.10 × 1.60 × 10⁻¹⁹) = {sf(1e-13 / (0.1 * QE))} m s⁻¹', ['C1: rearranged', 'C1: substitution'], aq='v')
N('M', 4, 'An electron is accelerated from rest through 500 V and then moves at right angles to a field of 0.010 T. Calculate the magnetic force on it, in units of 10⁻¹⁴ N.' + take('e', 'me'), QE * sqrt(2 * QE * 500 / ME) * 0.010, '10⁻¹⁴ N',
  f'v = √(2eV/m) = √(2 × 1.60 × 10⁻¹⁹ × 500 ÷ 9.11 × 10⁻³¹) = {sf(sqrt(2 * QE * 500 / ME))} m s⁻¹. F = BQv = 0.010 × 1.60 × 10⁻¹⁹ × {sf(sqrt(2 * QE * 500 / ME), 4)} = {sf(0.01 * QE * sqrt(2 * QE * 500 / ME))} N', ['C1: ½mv² = eV', 'C1: speed', 'C1: F = BQv'], aq='F')
M('M', 3, 'Why are auroras seen mainly near the Earth\'s magnetic poles?', 'Charged particles from the Sun spiral along the field lines, which converge and enter the atmosphere near the poles', ['The Earth\'s field repels particles from the equator', 'The poles are colder, so the air glows', 'Neutral particles are attracted to the poles'], 'Motion along the field is unaffected, so particles follow the field lines down near the poles.', ['C1: spiral along field lines', 'C1: lines enter atmosphere near poles'])
N('M', 3, 'An ion moving at 2.0 × 10⁵ m s⁻¹ at right angles to a 0.50 T field feels a force of 3.2 × 10⁻¹⁴ N. Calculate its charge, as a multiple of e.' + take('e'), 3.2e-14 / (0.50 * 2.0e5) / QE, None,
  'Q = F/(Bv) = 3.2 × 10⁻¹⁴ ÷ (0.50 × 2.0 × 10⁵) = 3.2 × 10⁻¹⁹ C, and 3.2 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 2.0', ['C1: Q = F/(Bv)', 'C1: ÷ e'], sig=2, aq='Q/e')
M('M', 4, 'The charge of a particle is doubled and its speed is halved, in the same field. What happens to the magnetic force on it?', 'It stays the same', ['It doubles', 'It halves', 'It quadruples'], 'F = BQv: doubling Q and halving v leaves the product Qv, and so F, unchanged.', ['C1: F ∝ Qv', 'C1: product unchanged', 'C1: same field'])
N('M', 3, 'A charged particle feels half the maximum possible magnetic force for its speed. Calculate the angle between its velocity and the field.', degrees(asin(0.5)), '°',
  'sin θ = 0.50, so θ = sin⁻¹ 0.50 = 30°', ['C1: F = F_max sin θ', 'C1: inverse sine'], sig=2, aq='θ')
N('M', 3, 'A singly charged ion moves at 4.0 × 10⁴ m s⁻¹ at right angles to a 0.60 T field in a mass spectrometer. Calculate the magnetic force on it, in units of 10⁻¹⁵ N.' + take('e'), QE * 4.0e4 * 0.60, '10⁻¹⁵ N',
  f'F = BQv = 0.60 × 1.60 × 10⁻¹⁹ × 4.0 × 10⁴ = {sf(0.6 * QE * 4e4)} N', ['C1: F = BQv', 'C1: substitution'], aq='F')
M('M', 3, 'Several beams pass at right angles through a magnetic field. Which beam is NOT deflected?', 'A beam of neutrons', ['A beam of protons', 'A beam of electrons', 'A beam of α-particles'], 'Neutrons carry no charge.', ['C1: force needs charge', 'C1: neutrons neutral'])
N('M', 4, 'An electron moves at 2.0 × 10⁶ m s⁻¹ at right angles to a field of 3.0 mT. Calculate its acceleration.' + take('e', 'me'), QE * 2.0e6 * 3.0e-3 / ME, 'm s⁻²',
  f'F = BQv = 3.0 × 10⁻³ × 1.60 × 10⁻¹⁹ × 2.0 × 10⁶ = {sf(3e-3 * QE * 2e6)} N. a = {sf(3e-3 * QE * 2e6, 4)} ÷ 9.11 × 10⁻³¹ = {sf(3e-3 * QE * 2e6 / ME)} m s⁻²', ['C1: field in T', 'C1: F = BQv', 'C1: a = F/m'], aq='a')
M('M', 3, 'An electron moves due north in a magnetic field that points vertically downwards. In which direction is the force on it?', 'Due east', ['Due west', 'Due south', 'Vertically upwards'], 'Conventional current is due south; left-hand rule with first finger down and second finger south gives a thumb pointing east.', ['C1: current opposite to electron velocity', 'C1: left-hand rule'])
# hard
N('H', 6, 'A copper wire of cross-sectional area 1.0 × 10⁻⁶ m² carries 5.0 A. Copper has 8.5 × 10²⁸ free electrons per m³. The wire lies at right angles to a field of 0.20 T. (a) Calculate the drift speed of the electrons. (b) Calculate the magnetic force on one electron, in units of 10⁻²³ N. (c) Show that the total force on all the free electrons in 0.10 m of wire equals BIL. Give only the answer to (b).' + take('e'), 0.20 * QE * 5.0 / (8.5e28 * 1.0e-6 * QE), '10⁻²³ N',
  f'(a) v = I/(nAe) = 5.0 ÷ (8.5 × 10²⁸ × 1.0 × 10⁻⁶ × 1.60 × 10⁻¹⁹) = {sf(5 / (8.5e28 * 1e-6 * QE))} m s⁻¹. (b) F = Bev = 0.20 × 1.60 × 10⁻¹⁹ × {sf(5 / (8.5e28 * 1e-6 * QE), 4)} = {sf(0.2 * QE * 5 / (8.5e28 * 1e-6 * QE))} N. (c) Number of electrons = nAL = 8.5 × 10²⁸ × 1.0 × 10⁻⁶ × 0.10 = 8.5 × 10²¹; total = 8.5 × 10²¹ × {sf(0.2 * QE * 5 / (8.5e28 * 1e-6 * QE), 4)} = 0.10 N, and BIL = 0.20 × 5.0 × 0.10 = 0.10 N.',
  ['C1: v = I/(nAe)', 'C1: F = Bev', 'C1: number of electrons nAL', 'M1: total force', 'B1: equals BIL'], aq='F')
N('H', 5, 'A proton in the solar wind moves at 4.0 × 10⁵ m s⁻¹ at right angles to the Earth\'s field, which is 3.0 × 10⁻⁵ T at that height. (a) Calculate the magnetic force on the proton. (b) Calculate its acceleration. (c) Explain why its speed does not change. Give only the answer to (b).' + take('e', 'mp'), QE * 4.0e5 * 3.0e-5 / MP, 'm s⁻²',
  f'(a) F = BQv = 3.0 × 10⁻⁵ × 1.60 × 10⁻¹⁹ × 4.0 × 10⁵ = {sf(3e-5 * QE * 4e5)} N. (b) a = {sf(3e-5 * QE * 4e5, 4)} ÷ 1.67 × 10⁻²⁷ = {sf(3e-5 * QE * 4e5 / MP)} m s⁻². (c) The force is always at right angles to the velocity, so it changes only the direction of motion.',
  ['C1: F = BQv', 'C1: a = F/m', 'C1: substitution', 'B1: perpendicular force, no work'], aq='a')
N('H', 6, 'An electron moves at 2.0 × 10⁶ m s⁻¹ at 30° to a uniform field of 5.0 mT. (a) Calculate the components of its velocity parallel and perpendicular to the field. (b) Calculate the radius of its helical path, using r = mv⊥/eB. (c) Calculate the time for one revolution, T = 2πm/eB. (d) Calculate the pitch of the helix (the distance moved along the field in one revolution), in cm. Give only the answer to (d).' + take('e', 'me'), 2.0e6 * cos(radians(30)) * 2 * pi * ME / (QE * 5.0e-3) * 100, 'cm',
  f'(a) v∥ = 2.0 × 10⁶ × cos 30° = {sf(2e6 * cos(radians(30)))} m s⁻¹; v⊥ = 2.0 × 10⁶ × sin 30° = 1.0 × 10⁶ m s⁻¹. (b) r = 9.11 × 10⁻³¹ × 1.0 × 10⁶ ÷ (1.60 × 10⁻¹⁹ × 5.0 × 10⁻³) = {sf(ME * 1e6 / (QE * 5e-3))} m. (c) T = 2π × 9.11 × 10⁻³¹ ÷ (1.60 × 10⁻¹⁹ × 5.0 × 10⁻³) = {sf(2 * pi * ME / (QE * 5e-3))} s. (d) Pitch = v∥T = {sf(2e6 * cos(radians(30)), 4)} × {sf(2 * pi * ME / (QE * 5e-3), 4)} = {sf(2e6 * cos(radians(30)) * 2 * pi * ME / (QE * 5e-3))} m. In cm: {sf(2e6 * cos(radians(30)) * 2 * pi * ME / (QE * 5e-3), 4)} × 100 = {sf(2e6 * cos(radians(30)) * 2 * pi * ME / (QE * 5e-3) * 100)}',
  ['C1: velocity components', 'C1: radius', 'C1: period', 'M1: pitch = v∥T', 'C1: conversion'], aq='pitch')
N('H', 5, 'Sea water flows at 2.0 m s⁻¹ along a horizontal channel 0.20 m wide, at right angles to a vertical field of 0.50 T. (a) Explain why positive and negative ions are pushed to opposite sides of the channel. (b) Calculate the magnetic force on an ion of charge e. (c) The separation continues until the electric field across the channel is vB. Calculate the p.d. across the channel. Give only the answer to (c).' + take('e'), 2.0 * 0.50 * 0.20, 'V',
  f'(a) F = BQv: ions of opposite sign moving the same way feel opposite forces. (b) F = 0.50 × 1.60 × 10⁻¹⁹ × 2.0 = {sf(0.5 * QE * 2)} N. (c) E = vB = 2.0 × 0.50 = 1.0 V m⁻¹, so V = Ed = 1.0 × 0.20 = 0.20 V',
  ['B1: opposite charges, opposite forces', 'C1: F = BQv', 'M1: E = vB at equilibrium', 'C1: V = Ed'], sig=2, aq='V')
N('H', 5, 'An ion of charge 3e moves at right angles to a field of 0.25 T and experiences a force of 1.2 × 10⁻¹³ N. (a) Calculate its speed. (b) Its mass is 6.6 × 10⁻²⁶ kg. Calculate its kinetic energy. (c) Explain why this kinetic energy stays constant in the field. Give only the answer to (a).' + take('e'), 1.2e-13 / (3 * QE * 0.25), 'm s⁻¹',
  f'(a) v = F/(BQ) = 1.2 × 10⁻¹³ ÷ (0.25 × 3 × 1.60 × 10⁻¹⁹) = {sf(1.2e-13 / (0.25 * 3 * QE))} m s⁻¹. (b) E_k = 0.5 × 6.6 × 10⁻²⁶ × ({sf(1.2e-13 / (0.25 * 3 * QE), 4)})² = {sf(0.5 * 6.6e-26 * (1.2e-13 / (0.25 * 3 * QE)) ** 2)} J. (c) The magnetic force does no work because it is perpendicular to the velocity.',
  ['C1: Q = 3e', 'C1: v = F/(BQ)', 'C1: ½mv²', 'B1: no work done'], aq='v')
N('H', 6, 'The magnetic force on electrons of fixed speed in a 0.10 T field is measured for different angles θ between their velocity and the field: θ/° = 0, 30, 60, 90 and F/10⁻¹⁴ N = 0, 2.4, 4.2, 4.8. (a) Show that F ∝ sin θ. (b) Use the reading at 90° to find the speed of the electrons. (c) Predict the force at 45°, in units of 10⁻¹⁴ N. Give only the answer to (b).' + take('e'), 4.8e-14 / (QE * 0.10), 'm s⁻¹',
  f'(a) F/sin θ = 2.4 ÷ 0.50 = 4.8, 4.2 ÷ 0.866 = {sf(4.2 / sin(radians(60)))} and 4.8 ÷ 1 = 4.8 (×10⁻¹⁴ N): constant. (b) v = F/(Be) = 4.8 × 10⁻¹⁴ ÷ (0.10 × 1.60 × 10⁻¹⁹) = 3.0 × 10⁶ m s⁻¹. (c) F = 4.8 × 10⁻¹⁴ × sin 45° = {sf(4.8e-14 * sin(radians(45)))} N',
  ['C1: F/sin θ values', 'B1: constant', 'C1: v = F/(Be)', 'C1: substitution', 'C1: prediction'], sig=2, aq='v')
N('H', 5, 'In a mass spectrometer, a singly charged ion of mass 4.0 × 10⁻²⁶ kg moves at 1.0 × 10⁵ m s⁻¹ at right angles to a field of 0.10 T. (a) Calculate the magnetic force. (b) Calculate its weight. (c) Calculate (magnetic force) ÷ (weight) and comment. Give only the ratio.' + take('e', 'g'), QE * 1.0e5 * 0.10 / (4.0e-26 * g), None,
  f'(a) F = 0.10 × 1.60 × 10⁻¹⁹ × 1.0 × 10⁵ = 1.6 × 10⁻¹⁵ N. (b) W = 4.0 × 10⁻²⁶ × 9.81 = {sf(4e-26 * 9.81)} N. (c) Ratio = 1.6 × 10⁻¹⁵ ÷ {sf(4e-26 * 9.81, 4)} = {sf(1.6e-15 / (4e-26 * 9.81))}: gravity is completely negligible.',
  ['C1: F = BQv', 'C1: W = mg', 'C1: ratio', 'B1: gravity negligible'], aq='ratio')
N('H', 6, 'Electrons are accelerated from rest through 1.2 kV and then enter a field of 0.80 mT at right angles. (a) Calculate their speed. (b) Calculate the magnetic force on each electron, in units of 10⁻¹⁵ N. (c) Calculate the acceleration. (d) Explain why they move in a circle. Give only the answer to (b).' + take('e', 'me'), QE * sqrt(2 * QE * 1200 / ME) * 0.80e-3, '10⁻¹⁵ N',
  f'(a) v = √(2 × 1.60 × 10⁻¹⁹ × 1200 ÷ 9.11 × 10⁻³¹) = {sf(sqrt(2 * QE * 1200 / ME))} m s⁻¹. (b) F = 0.80 × 10⁻³ × 1.60 × 10⁻¹⁹ × {sf(sqrt(2 * QE * 1200 / ME), 4)} = {sf(0.8e-3 * QE * sqrt(2 * QE * 1200 / ME))} N. (c) a = F/m = {sf(0.8e-3 * QE * sqrt(2 * QE * 1200 / ME), 4)} ÷ 9.11 × 10⁻³¹ = {sf(0.8e-3 * QE * sqrt(2 * QE * 1200 / ME) / ME)} m s⁻². (d) The force is constant in size and always perpendicular to the velocity, so it is a centripetal force.',
  ['C1: ½mv² = eV', 'C1: F = BQv', 'C1: a = F/m', 'B1: perpendicular constant force', 'B1: centripetal'], aq='F')
N('H', 5, 'A proton and an α-particle (charge 2e, mass 4mₚ) are accelerated from rest through the same p.d. and enter the same magnetic field at right angles. (a) Show that the α-particle\'s speed is 1/√2 of the proton\'s. (b) Calculate (magnetic force on α-particle) ÷ (magnetic force on proton). Give only the answer to (b).', 2 / sqrt(2), None,
  f'(a) ½mv² = QV gives v = √(2QV/m); for the α-particle Q/m is half that of the proton, so v is 1/√2 as large. (b) F = BQv: ratio = 2 × (1/√2) = √2 = {sf(sqrt(2))}',
  ['M1: v = √(2QV/m)', 'B1: v ratio 1/√2', 'C1: F ∝ Qv', 'C1: ratio'], aq='ratio')

# ═════════════════════════ 25.2 Orbiting charged particles (17/19/8) ═════════════════════════
lesson('25.2')
N('E', 2, 'A proton moves at 1.0 × 10⁶ m s⁻¹ at right angles to a field of 0.50 T. Calculate the radius of its circular path, in cm, using r = mv/BQ.' + take('mp', 'e'), MP * 1.0e6 / (0.50 * QE) * 100, 'cm',
  f'r = mv/BQ = 1.67 × 10⁻²⁷ × 1.0 × 10⁶ ÷ (0.50 × 1.60 × 10⁻¹⁹) = {sf(MP * 1e6 / (0.5 * QE))} m. In cm: {sf(MP * 1e6 / (0.5 * QE), 4)} × 100 = {sf(MP * 1e6 / (0.5 * QE) * 100)}', ['C1: r = mv/BQ'], aq='r')
M('E', 1, 'How is the equation r = mv/BQ for a charged particle in a magnetic field obtained?', 'By equating the magnetic force BQv to the centripetal force mv²/r', ['By equating BQv to mg', 'By equating BQv to ½mv²', 'By equating BQ to mv'], 'BQv = mv²/r gives r = mv/BQ.')
N('E', 2, 'An α-particle (mass 6.64 × 10⁻²⁷ kg, charge 2e) moves at 2.0 × 10⁶ m s⁻¹ at right angles to a 1.0 T field. Calculate the radius of its path.' + take('e'), MA * 2.0e6 / (1.0 * 2 * QE), 'm',
  f'r = mv/BQ = 6.64 × 10⁻²⁷ × 2.0 × 10⁶ ÷ (1.0 × 2 × 1.60 × 10⁻¹⁹) = {sf(MA * 2e6 / (2 * QE))} m', ['C1: Q = 2e in r = mv/BQ'], aq='r')
M('E', 1, 'The flux density acting on a circling charged particle is doubled. What happens to the radius of its path?', 'It halves', ['It doubles', 'It stays the same', 'It quadruples'], 'r = mv/BQ, so r ∝ 1/B.')
N('E', 2, 'A proton moves in a circle of radius 0.10 m in a field of 0.20 T. Calculate its momentum, in units of 10⁻²¹ kg m s⁻¹.' + take('e'), 0.20 * QE * 0.10, '10⁻²¹ kg m s⁻¹',
  f'p = mv = BQr = 0.20 × 1.60 × 10⁻¹⁹ × 0.10 = {sf(0.2 * QE * 0.1)} kg m s⁻¹', ['C1: p = BQr'], sig=2, aq='p')
M('E', 1, 'How does the time for one orbit of a charged particle in a uniform field depend on its speed?', 'It does not depend on the speed', ['It is proportional to the speed', 'It is inversely proportional to the speed', 'It is proportional to the speed squared'], 'T = 2πm/BQ: faster particles move in larger circles, taking the same time.')
N('E', 2, 'Calculate the period of a proton circling in a 1.0 T field, in ns, using T = 2πm/BQ.' + take('mp', 'e'), 2 * pi * MP / (1.0 * QE) * 1e9, 'ns',
  f'T = 2π × 1.67 × 10⁻²⁷ ÷ (1.0 × 1.60 × 10⁻¹⁹) = {sf(2 * pi * MP / QE)} s. In ns: {sf(2 * pi * MP / QE, 4)} × 10⁹ = {sf(2 * pi * MP / QE * 1e9)}', ['C1: T = 2πm/BQ'], aq='T')
M('E', 1, 'Two particles with the same charge and speed enter the same magnetic field. Particle X has the larger mass. Which statement is correct?', 'X moves in the larger circle', ['X moves in the smaller circle', 'They move in circles of equal size', 'X is not deflected'], 'r = mv/BQ, so with v, B and Q the same the radius is proportional to the mass.')
N('E', 2, 'An electron moves in a circle of radius 2.0 cm in a field of 1.0 mT. Calculate its speed.' + take('e', 'me'), QE * 1.0e-3 * 0.020 / ME, 'm s⁻¹',
  f'v = BQr/m = 1.0 × 10⁻³ × 1.60 × 10⁻¹⁹ × 0.020 ÷ 9.11 × 10⁻³¹ = {sf(1e-3 * QE * 0.02 / ME)} m s⁻¹', ['C1: v = BQr/m'], aq='v')
M('E', 1, 'A proton and an electron move in the same magnetic field. How do their senses of rotation compare?', 'They circle in opposite senses', ['They circle in the same sense', 'Only the proton circles', 'Only the electron circles'], 'Opposite charges feel opposite forces for the same velocity.')
N('E', 2, 'Calculate the frequency at which an electron circles in a field of 0.10 T, in GHz, using f = BQ/2πm.' + take('e', 'me'), 0.10 * QE / (2 * pi * ME) / 1e9, 'GHz',
  f'f = 0.10 × 1.60 × 10⁻¹⁹ ÷ (2π × 9.11 × 10⁻³¹) = {sf(0.1 * QE / (2 * pi * ME))} Hz. In GHz: {sf(0.1 * QE / (2 * pi * ME), 4)} ÷ 10⁹ = {sf(0.1 * QE / (2 * pi * ME) / 1e9)}', ['C1: f = BQ/2πm'], aq='f')
M('E', 1, 'What provides the centripetal force on a charged particle moving in a circle in a uniform magnetic field?', 'The magnetic force on the moving charge', ['Its weight', 'An electric field', 'The particle\'s own inertia'], 'BQv acts towards the centre of the circle.')
N('E', 2, 'Calculate the flux density needed to make a proton moving at 5.0 × 10⁶ m s⁻¹ follow a circle of radius 0.50 m.' + take('mp', 'e'), MP * 5.0e6 / (QE * 0.50), 'T',
  f'B = mv/(Qr) = 1.67 × 10⁻²⁷ × 5.0 × 10⁶ ÷ (1.60 × 10⁻¹⁹ × 0.50) = {sf(MP * 5e6 / (QE * 0.5))} T', ['C1: rearranged r = mv/BQ'], aq='B')
M('E', 1, 'The speed of a charged particle circling in a uniform magnetic field doubles. What happens to the radius?', 'It doubles', ['It halves', 'It stays the same', 'It quadruples'], 'r = mv/BQ, so the radius is proportional to the speed and doubles with it.')
N('E', 1, 'Calculate the angular speed of a proton circling in a 0.50 T field, using ω = BQ/m.' + take('e', 'mp'), 0.50 * QE / MP, 'rad s⁻¹',
  f'ω = 0.50 × 1.60 × 10⁻¹⁹ ÷ 1.67 × 10⁻²⁷ = {sf(0.5 * QE / MP)} rad s⁻¹', [], aq='ω')
M('E', 1, 'What happens to the kinetic energy of a charged particle as it circles in a uniform magnetic field?', 'It stays constant', ['It increases each orbit', 'It decreases each orbit', 'It is zero'], 'The magnetic force does no work.')
N('E', 2, 'A singly charged ion of mass 3.8 × 10⁻²⁶ kg moves at 1.0 × 10⁵ m s⁻¹ at right angles to a field of 0.25 T. Calculate the radius of its path.' + take('e'), 3.8e-26 * 1.0e5 / (0.25 * QE), 'm',
  f'r = mv/BQ = 3.8 × 10⁻²⁶ × 1.0 × 10⁵ ÷ (0.25 × 1.60 × 10⁻¹⁹) = {sf(3.8e-26 * 1e5 / (0.25 * QE))} m', ['C1: r = mv/BQ'], aq='r')
# medium
N('M', 3, 'Electrons accelerated from rest through 200 V enter a field of 1.0 mT at right angles. Calculate the radius of their path, in cm.' + take('e', 'me'), ME * sqrt(2 * QE * 200 / ME) / (QE * 1.0e-3) * 100, 'cm',
  f'v = √(2 × 1.60 × 10⁻¹⁹ × 200 ÷ 9.11 × 10⁻³¹) = {sf(sqrt(2 * QE * 200 / ME))} m s⁻¹. r = 9.11 × 10⁻³¹ × {sf(sqrt(2 * QE * 200 / ME), 4)} ÷ (1.60 × 10⁻¹⁹ × 1.0 × 10⁻³) = {sf(ME * sqrt(2 * QE * 200 / ME) / (QE * 1e-3))} m. In cm: {sf(ME * sqrt(2 * QE * 200 / ME) / (QE * 1e-3), 4)} × 100 = {sf(ME * sqrt(2 * QE * 200 / ME) / (QE * 1e-3) * 100)}', ['C1: speed from eV = ½mv²', 'C1: r = mv/BQ'], aq='r')
N('M', 3, 'A proton moves in a circle of radius 0.30 m in a 0.50 T field. Calculate its kinetic energy, in MeV (1 MeV = 1.6 × 10⁻¹³ J).' + take('e', 'mp'), (0.50 * QE * 0.30) ** 2 / (2 * MP) / 1.6e-13, 'MeV',
  f'p = BQr = 0.50 × 1.60 × 10⁻¹⁹ × 0.30 = 2.4 × 10⁻²⁰ kg m s⁻¹. E_k = p²/2m = (2.4 × 10⁻²⁰)² ÷ (2 × 1.67 × 10⁻²⁷) = {sf((2.4e-20) ** 2 / (2 * MP))} J. In MeV: {sf((2.4e-20) ** 2 / (2 * MP), 4)} ÷ 1.6 × 10⁻¹³ = {sf((2.4e-20) ** 2 / (2 * MP) / 1.6e-13)}', ['C1: p = BQr', 'C1: E_k = p²/2m'], aq='E_k')
M('M', 3, 'Two singly charged isotopes, of masses m and 1.1m, enter the same magnetic field at the same speed. What is the ratio of their radii (heavier ÷ lighter)?', '1.1', ['1/1.1', '1.21', '1.0'], 'r = mv/BQ ∝ m at the same v and Q.', ['C1: r ∝ m', 'C1: ratio 1.1'])
N('M', 4, 'In a mass spectrometer, singly charged ions are accelerated from rest through 2000 V and enter a field of 0.20 T at right angles. An ion follows a circle of radius 0.144 m. Using m = QB²r²/2V, calculate its mass, in units of 10⁻²⁶ kg.' + take('e'), QE * 0.20 ** 2 * 0.144 ** 2 / (2 * 2000), '10⁻²⁶ kg',
  f'm = QB²r²/2V = 1.60 × 10⁻¹⁹ × 0.20² × 0.144² ÷ (2 × 2000) = {sf(QE * 0.04 * 0.144 ** 2 / 4000)} kg', ['M1: m = QB²r²/2V', 'C1: substitution', 'C1: value'], aq='m')
N('M', 3, 'An electron and a proton circle in the same magnetic field. Calculate (period of electron) ÷ (period of proton).' + take('me', 'mp'), ME / MP, None,
  f'T = 2πm/BQ ∝ m for equal |Q|: ratio = 9.11 × 10⁻³¹ ÷ 1.67 × 10⁻²⁷ = {sf(ME / MP)}', ['C1: T ∝ m', 'C1: ratio'], aq='ratio')
M('M', 3, 'Why does the time for one orbit not change when a charged particle in a uniform magnetic field speeds up?', 'Its radius increases in proportion to its speed, so the circumference grows at the same rate as the speed', ['Its speed cannot change in a magnetic field', 'The field gets weaker as the particle speeds up', 'Its mass decreases as it speeds up'], 'T = 2πr/v = 2πm/BQ, independent of v.', ['C1: r ∝ v', 'C1: T = 2πr/v constant'])
N('M', 3, 'A proton and an α-particle (mass 6.64 × 10⁻²⁷ kg, charge 2e) move at the same speed at right angles to the same field. Calculate (radius for α-particle) ÷ (radius for proton).' + take('mp'), (MA / 2) / MP, None,
  f'r ∝ m/Q: ratio = (6.64 × 10⁻²⁷ ÷ 2) ÷ 1.67 × 10⁻²⁷ = {sf(MA / 2 / MP)}', ['C1: r ∝ m/Q', 'C1: substitution'], aq='ratio')
N('M', 4, 'A cyclotron has dees of radius 0.50 m in a field of 1.5 T. Calculate the maximum kinetic energy of the protons it produces, in MeV (1 MeV = 1.6 × 10⁻¹³ J).' + take('e', 'mp'), 0.5 * MP * (QE * 1.5 * 0.50 / MP) ** 2 / 1.6e-13, 'MeV',
  f'v_max = BQr/m = 1.5 × 1.60 × 10⁻¹⁹ × 0.50 ÷ 1.67 × 10⁻²⁷ = {sf(1.5 * QE * 0.5 / MP)} m s⁻¹. E_k = 0.5 × 1.67 × 10⁻²⁷ × ({sf(1.5 * QE * 0.5 / MP, 4)})² = {sf(0.5 * MP * (1.5 * QE * 0.5 / MP) ** 2)} J. In MeV: {sf(0.5 * MP * (1.5 * QE * 0.5 / MP) ** 2, 4)} ÷ 1.6 × 10⁻¹³ = {sf(0.5 * MP * (1.5 * QE * 0.5 / MP) ** 2 / 1.6e-13)}', ['C1: v = BQr/m', 'C1: ½mv²', 'C1: conversion to MeV'], aq='E_k')
M('M', 3, 'In a cloud chamber in a magnetic field, a charged particle\'s track is a spiral of decreasing radius. Why?', 'The particle loses kinetic energy by ionising the gas, so its speed and radius decrease', ['The magnetic field is getting stronger', 'The particle is gaining charge', 'The magnetic force does work on it'], 'r = mv/BQ, and v falls as energy is lost in collisions.', ['C1: energy lost to ionisation', 'C1: r ∝ v'])
N('M', 3, 'Calculate the frequency of the alternating p.d. needed in a cyclotron to accelerate protons in a field of 1.2 T, in MHz.' + take('e', 'mp'), 1.2 * QE / (2 * pi * MP) / 1e6, 'MHz',
  f'f = BQ/2πm = 1.2 × 1.60 × 10⁻¹⁹ ÷ (2π × 1.67 × 10⁻²⁷) = {sf(1.2 * QE / (2 * pi * MP))} Hz. In MHz: {sf(1.2 * QE / (2 * pi * MP), 4)} ÷ 10⁶ = {sf(1.2 * QE / (2 * pi * MP) / 1e6)}', ['C1: f = BQ/2πm', 'C1: conversion'], aq='f')
N('M', 3, 'A charged particle circles with radius 1.5 cm in a uniform field. Its speed is tripled. Calculate the new radius, in cm.', 1.5 * 3, 'cm',
  'r ∝ v, so r = 1.5 × 3 = 4.5 cm', ['C1: r ∝ v', 'C1: value'], sig=2, aq='r')
M('M', 4, 'A uniform magnetic field points into the page. A particle moving across the page curves clockwise. What is the sign of its charge?', 'Negative', ['Positive', 'It is uncharged', 'It cannot be decided'], 'For a positive charge, F = Qv × B with B into the page turns the path anticlockwise; clockwise means negative.', ['C1: left-hand rule for positive charge', 'C1: positive gives anticlockwise', 'C1: so negative'])
N('M', 3, 'A charged particle moves in a circle of radius 0.020 m and completes each orbit in 1.0 × 10⁻⁷ s. Calculate its speed.', 2 * pi * 0.020 / 1.0e-7, 'm s⁻¹',
  f'v = 2πr/T = 2π × 0.020 ÷ 1.0 × 10⁻⁷ = {sf(2 * pi * 0.02 / 1e-7)} m s⁻¹', ['C1: v = 2πr/T', 'C1: substitution'], aq='v')
N('M', 3, 'An electron completes one orbit in a uniform magnetic field every 3.57 × 10⁻⁹ s. Calculate the flux density, in mT.' + take('e', 'me'), 2 * pi * ME / (QE * 3.57e-9) * 1000, 'mT',
  f'B = 2πm/(QT) = 2π × 9.11 × 10⁻³¹ ÷ (1.60 × 10⁻¹⁹ × 3.57 × 10⁻⁹) = {sf(2 * pi * ME / (QE * 3.57e-9))} T. In mT: {sf(2 * pi * ME / (QE * 3.57e-9), 4)} × 1000 = {sf(2 * pi * ME / (QE * 3.57e-9) * 1000)}', ['C1: rearranged T = 2πm/BQ', 'C1: conversion'], aq='B')
M('M', 3, 'The direction of the magnetic field acting on a circling charged particle is reversed. What happens to its orbit?', 'It has the same radius but is traversed in the opposite sense', ['Its radius halves', 'It becomes a straight line', 'Its radius doubles'], 'The size of BQv is unchanged; its direction reverses.', ['C1: same |F|', 'C1: opposite sense'])
N('M', 4, 'A deuteron (mass 2mₚ, charge e) and a proton are accelerated from rest through the same p.d. and enter the same magnetic field. Calculate (radius for deuteron) ÷ (radius for proton).', sqrt(2), None,
  f'r = mv/BQ with v = √(2QV/m) gives r = √(2mV/Q)/B, so r ∝ √(m/Q): ratio = √2 = {sf(sqrt(2))}', ['M1: r = √(2mV/Q)/B', 'C1: r ∝ √m for equal Q', 'C1: ratio'], aq='ratio')
N('M', 3, 'An electron moves at 1.0 × 10⁶ m s⁻¹ at right angles to the Earth\'s field of 5.0 × 10⁻⁵ T. Calculate the radius of its path.' + take('me', 'e'), ME * 1.0e6 / (QE * 5.0e-5), 'm',
  f'r = mv/BQ = 9.11 × 10⁻³¹ × 1.0 × 10⁶ ÷ (1.60 × 10⁻¹⁹ × 5.0 × 10⁻⁵) = {sf(ME * 1e6 / (QE * 5e-5))} m', ['C1: r = mv/BQ', 'C1: substitution'], aq='r')
M('M', 3, 'Several different particles circle in the same uniform magnetic field. Which quantity is the same for all those with the same charge-to-mass ratio?', 'The time for one orbit', ['The radius of the orbit', 'The speed', 'The kinetic energy'], 'T = 2πm/BQ depends only on m/Q and B.', ['C1: T depends on m/Q', 'C1: not on speed'])
N('M', 3, 'Find the kinetic energy, in eV, of an electron whose path in a 1.0 mT field is a circle of radius 5.0 cm.' + take('e', 'me'), 0.5 * ME * (QE * 1.0e-3 * 0.050 / ME) ** 2 / QE, 'eV',
  f'v = BQr/m = 1.0 × 10⁻³ × 1.60 × 10⁻¹⁹ × 0.050 ÷ 9.11 × 10⁻³¹ = {sf(1e-3 * QE * 0.05 / ME)} m s⁻¹. E_k = 0.5 × 9.11 × 10⁻³¹ × ({sf(1e-3 * QE * 0.05 / ME, 4)})² = {sf(0.5 * ME * (1e-3 * QE * 0.05 / ME) ** 2)} J. In eV: {sf(0.5 * ME * (1e-3 * QE * 0.05 / ME) ** 2, 4)} ÷ 1.60 × 10⁻¹⁹ = {sf(0.5 * ME * (1e-3 * QE * 0.05 / ME) ** 2 / QE)}', ['C1: v = BQr/m', 'C1: E_k in eV'], aq='E_k')
